(7688218, 1259192, 4008, '<td valign="top">I normally don''t like strong processed images but this one works really well. The lovely soft colour tones, the softness of the whole image, the bright colour of the bird. I love it. In my top 3.</td>', 'I normally don''t like strong processed images but this one works really well. The lovely soft colour tones, the softness of the whole image, the bright colour of the bird. I love it. In my top 3.', '2021-02-28 11:49:44.000000', NULL, 1),
(7688224, 1259237, 4008, '<td valign="top">Great atmosphere. Love the movement. A pity the sun is touching the boy''s head, but that''s a minor point. top 5</td>', 'Great atmosphere. Love the movement. A pity the sun is touching the boy''s head, but that''s a minor point. top 5', '2021-02-28 11:50:34.000000', NULL, 1),
(7688225, 1259247, 4008, '<td valign="top">This is great. I can almost feel being there, sitting on the edge of a bed, just contemplating the day and watching time pass by outside. Love the warm colour and structure on the walls. top 5</td>', 'This is great. I can almost feel being there, sitting on the edge of a bed, just contemplating the day and watching time pass by outside. Love the warm colour and structure on the walls. top 5', '2021-02-28 11:50:37.000000', NULL, 1),
